        // --- products (182 records) ---
        \DB::table('products')->insert([
            'id' => 1,
            'category_id' => 9,
            'name' => "Holographic Stickers",
            'slug' => "holographic-stickers",
            'type' => "sticker",
            'description' => "Make your stickers unforgettable with our premium holographic vinyl material. The iridescent rainbow finish creates a stunning prismatic effect that changes with the light. Perfect for promotional stickers, product labels, social media giveaways, and any application where you want to stand out.",
            'image' => "images/products/holographic-stickers.jpg",
            'hero_title' => "Holographic Stickers",
            'hero_subtitle' => "Iridescent rainbow holographic vinyl stickers that catch light and attention.",
            'hero_image' => "images/products/holographic-stickers.jpg",
            'features' => "[\"Iridescent rainbow holographic finish creates stunning prismatic light effects\", \"Full-color digital printing over premium holographic base material\", \"Premium adhesive vinyl backing ensures long-lasting bond\", \"Waterproof and weather resistant for indoor and outdoor use\", \"Available in any custom shape to match your design perfectly\", \"Minimum order: 50 pieces with fast 3-5 business day production\"]",
            'steps_title' => "How to Order Holographic Stickers",
            'steps' => "[{\"title\": \"Choose Your Design\", \"description\": \"Upload your artwork \\u2014 holographic material makes any design pop.\"}, {\"title\": \"Select Size and Shape\", \"description\": \"Pick from standard sizes or specify custom dimensions.\"}, {\"title\": \"Choose Quantity\", \"description\": \"Volume discounts available for larger orders.\"}, {\"title\": \"Approve Digital Proof\", \"description\": \"Review your holographic proof within 4 hours of ordering.\"}, {\"title\": \"Production and Delivery\", \"description\": \"3-5 business days production with shipping to your door.\"}]",
            'concerns' => "[{\"title\":\"Are holographic stickers waterproof?\",\"description\":\"Yes! Our holographic stickers are made with waterproof vinyl material and a protective laminate coating. They withstand rain, spills, and even dishwasher cycles without fading or peeling.\"},{\"title\":\"How long do holographic stickers last?\",\"description\":\"Our holographic stickers are designed to last 3-5 years outdoors and even longer indoors. The UV-resistant laminate prevents fading, and the waterproof material ensures durability in all weather conditions.\"},{\"title\":\"What file format should I use for my design?\",\"description\":\"We accept AI, PDF, PSD, EPS, and high-resolution PNG files. For the best holographic effect, we recommend vector formats (AI or PDF) with clearly defined areas for the holographic effect.\"},{\"title\":\"What is the minimum order quantity?\",\"description\":\"Our minimum order for holographic stickers is just 50 pieces. We offer quantity discounts for larger orders, making it affordable for both small businesses and large enterprises.\"}]",
            'testimonials' => "[{\"name\": \"Rachel Green\", \"country\": \"United Kingdom\", \"avatar\": \"/images/testimonials/avatar-10.jpg\", \"text\": \"The holographic effect is absolutely stunning. Photos do not capture the shimmer - it is even better in person.\", \"rating\": 5}, {\"name\": \"Jennifer Lee\", \"country\": \"Canada\", \"avatar\": \"/images/testimonials/avatar-44.jpg\", \"text\": \"Our tech startup uses these for product launches and they always draw attention. Great conversation starter.\", \"rating\": 5}, {\"name\": \"Carlos Mendez\", \"country\": \"Mexico\", \"avatar\": \"/images/testimonials/avatar-11.jpg\", \"text\": \"Premium quality holographic film that catches light from every angle. Worth every penny spent.\", \"rating\": 5}]",
            'is_active' => 1,
            'sort_order' => 1,
            'created_at' => "2026-05-20 10:42:34",
            'updated_at' => "2026-05-20 11:40:38",
        ]);

        \DB::table('products')->insert([
            'id' => 2,
            'category_id' => 1,
            'name' => "Die Cut Stickers",
            'slug' => "die-cut-stickers",
            'type' => "sticker",
            'description' => "Our custom die-cut stickers are cut precisely to your design outline — no wasted white backing, just your artwork. Printed on premium vinyl with eco-friendly inks in stunning full color. Waterproof, scratch-resistant, and built to last. Perfect for product labels, brand packaging, promotional giveaways, and creative projects.",
            'image' => "images/products/die-cut-stickers.jpg",
            'hero_title' => "Custom Die Cut Stickers",
            'hero_subtitle' => "Vibrant, durable die-cut stickers in any shape and size. Premium vinyl with full color printing.",
            'hero_image' => "images/products/die-cut-stickers.jpg",
            'features' => "[\"Precision die-cut technology cuts exactly to your design outline\", \"Premium vinyl material with vibrant full-color printing\", \"Waterproof and scratch-resistant for lasting durability\", \"Choose glossy or matte laminate finish for your stickers\", \"Indoor and outdoor durability lasting 3-5 years\", \"Custom shapes and sizes available from 0.5\\\" to 12\\\"\"]",
            'steps_title' => "How to Order Die Cut Stickers",
            'steps' => "[{\"title\": \"Upload Your Design\", \"description\": \"Upload artwork in AI, EPS, PDF, or high-res PNG with transparent background.\"}, {\"title\": \"Select Options\", \"description\": \"Choose size, material, finish, and quantity.\"}, {\"title\": \"Review Proof\", \"description\": \"Digital proof within 4 hours. We check color and resolution.\"}, {\"title\": \"Approve and Produce\", \"description\": \"Production starts after your approval. We keep you updated.\"}, {\"title\": \"Receive and Enjoy\", \"description\": \"Carefully packaged and shipped to your door.\"}]",
            'concerns' => "[{\"title\":\"What is the difference between die cut and kiss cut?\",\"description\":\"Die cut stickers are cut all the way through both the sticker and backing material, creating individual stickers in your custom shape. Kiss cut stickers are cut only through the top layer, leaving them on a larger backing sheet.\"},{\"title\":\"Can you do intricate designs with die cutting?\",\"description\":\"Yes! Our advanced cutting technology can handle intricate designs with fine details. However, we recommend avoiding extremely thin or narrow elements (under 2mm) for the best results.\"},{\"title\":\"Are die cut stickers suitable for outdoor use?\",\"description\":\"Absolutely! Our die cut stickers are made with waterproof vinyl and UV-resistant inks. They can withstand sun, rain, and temperature changes for 3-5 years outdoors.\"},{\"title\":\"How accurate is the die cutting?\",\"description\":\"Our cutting precision is within 1mm accuracy. We provide a free digital proof before production so you can verify the cut line matches your design perfectly.\"}]",
            'testimonials' => "[{\"name\": \"Michael Chen\", \"country\": \"Canada\", \"avatar\": \"/images/testimonials/avatar-45.jpg\", \"text\": \"Great quality stickers at a fair price. Printing is clear and adhesive holds up well over time.\", \"rating\": 5}, {\"name\": \"Andreas Mueller\", \"country\": \"Germany\", \"avatar\": \"/images/testimonials/avatar-15.jpg\", \"text\": \"We have been ordering for months now. Consistent quality every single time without fail.\", \"rating\": 5}, {\"name\": \"Erik Lindberg\", \"country\": \"Sweden\", \"avatar\": \"/images/testimonials/avatar-54.jpg\", \"text\": \"Fast production and reliable delivery. The stickers arrived well-packaged and in perfect condition.\", \"rating\": 5}]",
            'is_active' => 1,
            'sort_order' => 2,
            'created_at' => "2026-05-20 10:42:34",
            'updated_at' => "2026-05-20 11:40:38",
        ]);

        \DB::table('products')->insert([
            'id' => 3,
            'category_id' => 5,
            'name' => "Vinyl Stickers",
            'slug' => "vinyl-stickers",
            'type' => "sticker",
            'description' => "Our vinyl sticker sheets feature premium adhesive vinyl printed with eco-friendly inks in vibrant full color. Waterproof and UV-resistant, these stickers last for years indoors and outdoors. Perfect for product labels, brand packaging, promotional giveaways, and more. Available in any custom size and shape with fast production.",
            'image' => "images/products/vinyl-stickers.jpg",
            'hero_title' => "Premium Vinyl Sticker Sheets",
            'hero_subtitle' => "Waterproof vinyl stickers printed in full color. Perfect for products, packaging, and branding.",
            'hero_image' => "images/products/vinyl-stickers.jpg",
            'features' => "[\"Premium outdoor-grade vinyl material for extreme durability\", \"UV-resistant inks prevent fading for 5+ years outdoors\", \"100% waterproof and weatherproof in all conditions\", \"Scratch and abrasion resistant for tough applications\", \"Custom shapes and sizes with any design accepted\", \"Ideal for vehicles, equipment, and outdoor signage\"]",
            'steps_title' => "How to Order Custom Vinyl Stickers",
            'steps' => "[{\"title\": \"Choose Your Size and Shape\", \"description\": \"Select from standard sizes or enter custom dimensions. Pick die-cut, kiss-cut, or custom shape.\"}, {\"title\": \"Upload Your Design\", \"description\": \"Upload your artwork in AI, EPS, PDF, or high-res PNG format. We accept vector files for best quality.\"}, {\"title\": \"Select Quantity and Finish\", \"description\": \"Choose your quantity for volume pricing. Select glossy or matte finish for your stickers.\"}, {\"title\": \"Review and Approve Proof\", \"description\": \"We will send a digital proof within 4 hours. Approve or request changes before production begins.\"}, {\"title\": \"Fast Production and Shipping\", \"description\": \"Production takes 3-5 business days. Choose standard or expedited shipping at checkout.\"}]",
            'concerns' => "[{\"title\":\"Can vinyl stickers be used on cars?\",\"description\":\"Yes! Our vinyl stickers are perfect for vehicle applications. They are car wash safe, UV-resistant, and can withstand extreme temperatures. Many customers use them for car decals and bumper stickers.\"},{\"title\":\"Are vinyl stickers dishwasher safe?\",\"description\":\"Yes, our vinyl stickers are dishwasher safe. The waterproof laminate coating protects the print through multiple wash cycles, making them great for water bottles, mugs, and tumblers.\"},{\"title\":\"What thickness are your vinyl stickers?\",\"description\":\"Our standard vinyl stickers are approximately 0.15mm thick (including laminate). This provides the ideal balance of durability and flexibility for most applications.\"},{\"title\":\"Can vinyl stickers be removed without damage?\",\"description\":\"While our vinyl stickers use a permanent adhesive, they can be removed from most surfaces with heat (hair dryer) and gentle peeling. Some residue may remain on porous surfaces.\"}]",
            'testimonials' => "[{\"name\": \"Marco Rossi\", \"country\": \"Italy\", \"avatar\": \"/images/testimonials/avatar-56.jpg\", \"text\": \"Great quality stickers at a fair price. Printing is clear and adhesive holds up well over time.\", \"rating\": 5}, {\"name\": \"Roberto Sanchez\", \"country\": \"Mexico\", \"avatar\": \"/images/testimonials/avatar-49.jpg\", \"text\": \"We have been ordering for months now. Consistent quality every single time without fail.\", \"rating\": 5}, {\"name\": \"Maria Lopez\", \"country\": \"Spain\", \"avatar\": \"/images/testimonials/avatar-59.jpg\", \"text\": \"Fast production and reliable delivery. The stickers arrived well-packaged and in perfect condition.\", \"rating\": 5}]",
            'is_active' => 1,
            'sort_order' => 3,
            'created_at' => "2026-05-20 10:42:34",
            'updated_at' => "2026-05-20 11:40:38",
        ]);

        \DB::table('products')->insert([
            'id' => 4,
            'category_id' => 17,
            'name' => "Logo Stickers",
            'slug' => "logo-stickers",
            'type' => "sticker",
            'description' => "Turn your brand logo into high-quality stickers that promote your business everywhere they go. Custom logo stickers are one of the most cost-effective marketing tools — they build brand awareness every time someone sees them. Available in all our premium materials including vinyl, holographic, metallic, and clear.",
            'image' => "images/products/logo-stickers.jpg",
            'hero_title' => "Custom Logo Stickers",
            'hero_subtitle' => "Premium logo stickers for brand promotion, packaging, and merchandise.",
            'hero_image' => "images/products/logo-stickers.jpg",
            'features' => "[\"Print your brand logo in stunning full-color detail\", \"Premium vinyl, holographic, and metallic material options\", \"Perfect for product packaging, merchandise, and branding\", \"Waterproof and durable for long-lasting brand exposure\", \"Custom shapes that match your logo outline exactly\", \"Volume discounts available for orders over 500 pieces\"]",
            'steps_title' => "How to Order Logo Stickers",
            'steps' => "[{\"title\": \"Upload Your Logo\", \"description\": \"Vector files (AI, EPS) preferred for best quality. We also accept high-res PNG.\"}, {\"title\": \"Select Material and Shape\", \"description\": \"Choose from vinyl, holographic, metallic, or clear materials.\"}, {\"title\": \"Choose Size and Quantity\", \"description\": \"Select your dimensions and quantity for volume pricing.\"}, {\"title\": \"Review Proof\", \"description\": \"Digital proof within 4 hours. Unlimited revisions until you are happy.\"}, {\"title\": \"Production and Shipping\", \"description\": \"Fast production with tracking and insured shipping.\"}]",
            'concerns' => "[{\"title\":\"Can you match my exact brand colors?\",\"description\":\"Yes! We offer Pantone (PMS) color matching for precise brand color reproduction. Simply provide your PMS numbers and we'll ensure accurate color matching across your entire order.\"},{\"title\":\"What if I don't have a vector logo file?\",\"description\":\"No problem! Our design team can convert your raster logo (PNG, JPG) into a vector format for free. We'll ensure it prints crisp and clean at any size.\"},{\"title\":\"Do you offer samples before bulk ordering?\",\"description\":\"Yes, we offer sample packs so you can evaluate our quality before placing a large order. Contact us for a free sample request.\"},{\"title\":\"Can I get different logo variations in one order?\",\"description\":\"Yes! We can print multiple logo variations within a single order. Each variation needs a minimum of 50 pieces. This is great for brands with multiple sub-brands or seasonal logos.\"}]",
            'testimonials' => "[{\"name\": \"Anna Janssen\", \"country\": \"Netherlands\", \"avatar\": \"/images/testimonials/avatar-53.jpg\", \"text\": \"Our company logo looks crisp and professional. Color matching was spot on with our brand guidelines.\", \"rating\": 5}, {\"name\": \"David Kim\", \"country\": \"South Korea\", \"avatar\": \"/images/testimonials/avatar-9.jpg\", \"text\": \"We hand these out at trade shows and the quality reflects well on our brand image.\", \"rating\": 5}, {\"name\": \"Ana Santos\", \"country\": \"Brazil\", \"avatar\": \"/images/testimonials/avatar-61.jpg\", \"text\": \"The logo resolution is excellent even on small stickers. Details are sharp and clear.\", \"rating\": 5}]",
            'is_active' => 1,
            'sort_order' => 4,
            'created_at' => "2026-05-20 10:42:35",
            'updated_at' => "2026-05-20 11:40:38",
        ]);

        \DB::table('products')->insert([
            'id' => 5,
            'category_id' => 23,
            'name' => "Food Labels",
            'slug' => "food-labels",
            'type' => "label",
            'description' => "Food labels that meet FDA labeling requirements and make your products look professional. From nutritional facts to ingredient lists, we handle the compliance details so you can focus on your products. Available in materials suitable for cold storage, refrigeration, and room temperature.",
            'image' => "images/products/food-labels.jpg",
            'hero_title' => "Custom Food Labels",
            'hero_subtitle' => "FDA-compliant food labels for restaurants, bakeries, and food manufacturers.",
            'hero_image' => "images/products/food-labels.jpg",
            'features' => "[\"FDA-compliant materials safe for direct food packaging contact\", \"Waterproof options perfect for refrigeration and freezing\", \"Custom nutritional facts and ingredient list printing\", \"Allergen information formatting to meet FDA requirements\", \"Vibrant full-color printing makes your products stand out\", \"No minimum order for digital printing flexibility\"]",
            'steps_title' => "How to Order Food Labels",
            'steps' => "[{\"title\": \"Share Your Requirements\", \"description\": \"Tell us about your product and packaging needs.\"}, {\"title\": \"Provide Product Information\", \"description\": \"Share nutritional data, ingredients, and allergen info.\"}, {\"title\": \"Design Review\", \"description\": \"We format all required information per FDA guidelines.\"}, {\"title\": \"Sample Approval\", \"description\": \"Request a sample before bulk production.\"}, {\"title\": \"Production and Delivery\", \"description\": \"Fast production with tracking included.\"}]",
            'concerns' => "[{\"title\":\"Do your food labels comply with FDA regulations?\",\"description\":\"Yes, all our food labels are produced with FDA-compliant materials and inks. We stay up-to-date with the latest FDA labeling requirements and can help ensure your labels meet all current regulations.\"},{\"title\":\"Can food labels withstand freezing temperatures?\",\"description\":\"Yes! We offer freezer-grade food labels with special adhesives that maintain their bond at temperatures as low as -40\\u00b0F (-40\\u00b0C). These labels won't peel or crack in freezer conditions.\"},{\"title\":\"What information is required on food labels?\",\"description\":\"FDA requires: product name, net weight, ingredient list, allergen warnings, nutrition facts, manufacturer\\/distributor info, and country of origin. Our team can help ensure your labels include all required information.\"},{\"title\":\"Can you print variable data on food labels?\",\"description\":\"Yes! We support variable data printing for lot numbers, expiration dates, barcodes, and other variable information. This is essential for food traceability and safety.\"}]",
            'testimonials' => "[{\"name\": \"Sofia Bianchi\", \"country\": \"Italy\", \"avatar\": \"/images/testimonials/avatar-57.jpg\", \"text\": \"FDA compliance was a must and these labels delivered. The documentation process was smooth and helpful.\", \"rating\": 5}, {\"name\": \"Emma Stone\", \"country\": \"Australia\", \"avatar\": \"/images/testimonials/avatar-40.jpg\", \"text\": \"The nutrition facts labels look professional and the variable data prints clearly every time.\", \"rating\": 5}, {\"name\": \"Carlos Garcia\", \"country\": \"Spain\", \"avatar\": \"/images/testimonials/avatar-58.jpg\", \"text\": \"Waterproof and oil-resistant. Our food container labels survive refrigerator and microwave use.\", \"rating\": 5}]",
            'is_active' => 1,
            'sort_order' => 5,
            'created_at' => "2026-05-20 10:42:35",
            'updated_at' => "2026-05-20 11:40:38",
        ]);

        \DB::table('products')->insert([
            'id' => 6,
            'category_id' => 20,
            'name' => "Candle Labels",
            'slug' => "candle-labels",
            'type' => "label",
            'description' => "Our custom candle labels meet all FTC and state compliance requirements while showcasing your brand beautifully. Waterproof materials that handle the heat of burning candles without peeling or discoloration. Available in any shape and size for container candles, pillar candles, and taper candles.",
            'image' => "images/products/candle-labels.jpg",
            'hero_title' => "Custom Candle Labels",
            'hero_subtitle' => "Professionally printed candle labels designed for compliance and brand impact.",
            'hero_image' => "images/products/candle-labels.jpg",
            'features' => "[\"Heat-resistant materials withstand burning candle temperatures\", \"Waterproof and oil-resistant for candle jar applications\", \"FTC and state-compliant labeling for candle safety\", \"Full-color custom printing with your brand design\", \"Available in shrink bands for tamper evidence\", \"Perfect for soy candles, wax melts, and soap labels\"]",
            'steps_title' => "How to Order Candle Labels",
            'steps' => "[{\"title\": \"Share Your Design\", \"description\": \"Upload your artwork or work with our design team.\"}, {\"title\": \"Choose Your Material\", \"description\": \"Select from waterproof vinyl, clear, or premium metallic materials.\"}, {\"title\": \"Add Compliance Info\", \"description\": \"We will help format required candle safety information per FTC guidelines.\"}, {\"title\": \"Review and Approve\", \"description\": \"Digital proof delivered within 4 hours with compliance checklist.\"}, {\"title\": \"Production and Ship\", \"description\": \"Fast production with careful packaging to prevent damage.\"}]",
            'concerns' => "[{\"title\":\"Will the labels withstand candle heat?\",\"description\":\"Yes! Our candle labels are specifically designed to withstand the heat generated by burning candles. They maintain their adhesion and appearance even when candles burn down to the label line.\"},{\"title\":\"Do you offer labels for different candle container shapes?\",\"description\":\"Absolutely! We make labels for glass jars, metal tins, ceramic containers, pillar candles, votives, and more. Just provide the dimensions and we'll create a custom fit.\"},{\"title\":\"Can I include safety warnings on my candle labels?\",\"description\":\"Yes! We can incorporate ASTM-standard candle safety warnings, CLP compliance information (for EU), and any other required safety text into your label design.\"},{\"title\":\"What is the minimum order for candle labels?\",\"description\":\"Our minimum order is 50 labels. We understand many candle makers are small businesses, so we keep our minimums low and offer competitive pricing for small batches.\"}]",
            'testimonials' => "[{\"name\": \"Sofia Bianchi\", \"country\": \"Italy\", \"avatar\": \"/images/testimonials/avatar-57.jpg\", \"text\": \"These candle labels are heat-resistant as promised. No bubbling or peeling near the flame area.\", \"rating\": 5}, {\"name\": \"Pedro Silva\", \"country\": \"Brazil\", \"avatar\": \"/images/testimonials/avatar-60.jpg\", \"text\": \"The kraft paper option gives our handmade candles that rustic artisan feel we were going for.\", \"rating\": 5}, {\"name\": \"Michael Chen\", \"country\": \"Canada\", \"avatar\": \"/images/testimonials/avatar-45.jpg\", \"text\": \"We offer custom scented candles and the labels look professional enough for retail shelving.\", \"rating\": 5}]",
            'is_active' => 1,
            'sort_order' => 6,
            'created_at' => "2026-05-20 10:42:35",
            'updated_at' => "2026-05-20 11:40:38",
        ]);

