            'question' => "What types of custom stickers do you offer?",
            'answer' => "We offer a wide variety of custom stickers including die cut stickers, kiss cut stickers, vinyl stickers, holographic stickers, clear/transparent stickers, foil stickers, glitter stickers, sticker rolls, and sticker sheets. Each type is available in multiple materials and finishes.",
