        \DB::table('faqs')->insert([
            'id' => 2,
            'product_id' => null,
            'category_id' => 2,
            'question' => "What materials are your stickers made from?",
            'answer' => "Our stickers are primarily made from premium vinyl (PVC) material with a protective laminate coating. We also offer paper stickers, clear polyester stickers, and specialty materials like holographic and metallic vinyl. All materials are selected for durability and print quality.",
            'sort_order' => 2,
            'is_active' => 1,
            'created_at' => "2026-05-20 10:42:35",
            'updated_at' => "2026-05-20 10:42:35",
        ]);

        \DB::table('faqs')->insert([
            'id' => 3,
            'product_id' => null,
            'category_id' => 3,
            'question' => "Are your stickers waterproof?",
            'answer' => "Yes! All our vinyl stickers are 100% waterproof. They can withstand rain, spills, and even dishwasher cycles. Our paper stickers are not waterproof but are suitable for indoor applications.",
            'sort_order' => 3,
            'is_active' => 1,
            'created_at' => "2026-05-20 10:42:35",
            'updated_at' => "2026-05-20 10:42:35",
        ]);

