            'category_id' => 6,
            'question' => "What file formats do you accept for sticker designs?",
            'answer' => "We accept AI, PDF, EPS, PSD, SVG, and high-resolution PNG/JPG files (300 DPI minimum). Vector formats (AI, PDF, EPS) are preferred for the best print quality and accurate die-cutting.",
