        \DB::table('faqs')->insert([
            'id' => 8,
            'product_id' => null,
            'category_id' => 8,
            'question' => "What is the difference between die cut and kiss cut stickers?",
            'answer' => "Die cut stickers are cut all the way through both the sticker and backing, creating individual stickers in your custom shape. Kiss cut stickers are cut only through the top vinyl layer, leaving them on a rectangular backing sheet — ideal for sticker sheets with multiple designs.",
            'sort_order' => 8,
            'is_active' => 1,
            'created_at' => "2026-05-20 10:42:36",
            'updated_at' => "2026-05-20 10:42:36",
        ]);

